// Package copyledger embeds the copy ledger, SlopChop's record of who wrote
// each string a visitor can read (copy/ledger.json). The AI page reports
// from it (docs/adr/2026-10-20-the-site-says-where-ai-is.md), so the figures
// a running site publishes are always those of the ledger it was built with:
// nothing is regenerated by hand, and nothing can go stale between a copy
// change and a release.
package copyledger

import _ "embed"

//go:embed ledger.json
var JSON []byte
